-- --------------------------------------------------------
-- Table structure for table `modules`
-- --------------------------------------------------------
DROP TABLE IF EXISTS `modules`;
CREATE TABLE IF NOT EXISTS `modules` (`id` INT AUTO_INCREMENT PRIMARY KEY, `title` VARCHAR(255) not null, `description` LONGTEXT, `thumbnail` VARCHAR(255), `content` LONGTEXT, `category` VARCHAR(255), `created_at` DATETIME, `updated_at` DATETIME) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Dumping data for table `modules`
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(1, 'Business Strategy Fundamentals', 'Pelajari dasar-dasar strategi bisnis yang efektif untuk mengembangkan usaha mikro dan kecil Anda.', NULL, 'Strategi bisnis adalah rencana tindakan jangka panjang yang dirancang untuk mencapai tujuan tertentu. Untuk pelaku UMKM, memiliki strategi yang jelas sangat penting.

Langkah-langkah membuat strategi bisnis:

1. Analisis SWOT - Identifikasi Strengths (kekuatan), Weaknesses (kelemahan), Opportunities (peluang), dan Threats (ancaman) bisnis Anda.

2. Tentukan Visi dan Misi - Visi adalah gambaran masa depan bisnis Anda, sedangkan misi adalah cara Anda mencapainya.

3. Tetapkan Target SMART - Specific, Measurable, Achievable, Relevant, Time-bound.

4. Identifikasi Keunggulan Kompetitif - Apa yang membuat produk/layanan Anda berbeda dari pesaing?

5. Buat Rencana Aksi - Breakdown target besar menjadi langkah-langkah kecil yang bisa dilakukan setiap hari/minggu.

6. Monitor dan Evaluasi - Tinjau pencapaian secara berkala dan sesuaikan strategi jika diperlukan.', 'Strategy', '2026-04-25 09:23:53', '2026-04-25 09:23:53');
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(2, 'Data Analysis for Microbusinesses', 'Cara menggunakan data sederhana untuk membuat keputusan bisnis yang lebih baik.', NULL, 'Data analysis tidak harus rumit. Sebagai pelaku UMKM, Anda bisa memulai dengan data sederhana yang sudah ada.

Jenis data yang bisa Anda analisis:

1. Data Penjualan - Produk mana yang paling laris? Kapan waktu penjualan tertinggi?

2. Data Pelanggan - Siapa pelanggan setia Anda? Apa yang mereka sering beli?

3. Data Keuangan - Berapa margin keuntungan setiap produk? Berapa biaya operasional bulanan?

4. Data Kompetitor - Apa yang dilakukan pesaing? Bagaimana harga mereka?

Tools gratis untuk analisis data UMKM:
- Google Sheets / Excel untuk pencatatan
- Google Analytics untuk website
- Insight Instagram/Facebook untuk media sosial
- Aplikasi kasir digital untuk penjualan', 'Data', '2026-04-25 09:23:53', '2026-04-25 09:23:53');
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(3, 'Effective Marketing Techniques', 'Teknik pemasaran modern yang efektif dengan budget terbatas untuk pelaku UMKM.', NULL, 'Pemasaran efektif tidak selalu membutuhkan budget besar. Berikut strategi yang bisa diterapkan:

1. Content Marketing - Buat konten edukatif tentang produk Anda di media sosial.

2. Social Media Marketing - Manfaatkan Instagram, TikTok, dan Facebook secara konsisten.

3. Word of Mouth - Berikan pengalaman terbaik agar pelanggan merekomendasikan Anda.

4. Community Building - Bangun komunitas pelanggan setia melalui grup WhatsApp atau Telegram.

5. Collaboration - Kolaborasi dengan UMKM lain untuk cross-promotion.

6. Google My Business - Daftarkan bisnis Anda agar mudah ditemukan di Google Maps.

7. Email/WhatsApp Marketing - Kirim update produk dan promo ke database pelanggan.', 'Marketing', '2026-04-25 09:23:53', '2026-04-25 09:23:53');
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(4, 'Financial Management for UMKM', 'Dasar-dasar pengelolaan keuangan yang sehat untuk usaha mikro dan kecil.', NULL, 'Pengelolaan keuangan yang baik adalah fondasi bisnis yang berkelanjutan.

Prinsip dasar keuangan UMKM:

1. Pisahkan Keuangan Pribadi dan Bisnis - Buat rekening terpisah untuk bisnis.

2. Catat Semua Transaksi - Gunakan buku kas atau aplikasi pencatatan keuangan.

3. Buat Anggaran Bulanan - Rencanakan pengeluaran dan pendapatan setiap bulan.

4. Kelola Arus Kas - Pastikan uang masuk selalu lebih besar dari uang keluar.

5. Sisihkan Dana Darurat - Simpan minimal 3-6 bulan biaya operasional.

6. Pahami Break Even Point - Ketahui kapan bisnis mulai menghasilkan keuntungan.', 'Finance', '2026-04-25 09:23:53', '2026-04-25 09:23:53');
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(5, 'Social Media Marketing', 'Strategi pemasaran media sosial untuk meningkatkan brand awareness dan penjualan.', NULL, 'Media sosial adalah alat pemasaran paling powerful untuk UMKM saat ini.

Platform yang direkomendasikan:

1. Instagram - Ideal untuk produk visual, fashion, makanan, craft.
2. TikTok - Cocok untuk konten kreatif dan menjangkau audiens muda.
3. Facebook - Baik untuk komunitas dan marketplace.
4. WhatsApp Business - Untuk komunikasi langsung dengan pelanggan.

Tips konten yang menarik:
- Gunakan foto/video berkualitas
- Ceritakan story di balik produk
- Tampilkan testimoni pelanggan
- Buat konten edukatif
- Post secara konsisten (minimal 3x seminggu)', 'Marketing', '2026-04-25 09:23:53', '2026-04-25 09:23:53');
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(6, 'Customer Service Excellence', 'Cara memberikan pelayanan pelanggan yang luar biasa untuk membangun loyalitas.', NULL, 'Pelayanan pelanggan yang excellent adalah kunci untuk mendapatkan pelanggan setia.

Prinsip customer service:

1. Responsif - Balas pesan pelanggan dalam waktu maksimal 1 jam.
2. Ramah dan Profesional - Gunakan bahasa yang sopan dan positif.
3. Solusi-Oriented - Fokus pada solusi, bukan masalah.
4. Personal Touch - Ingat nama dan preferensi pelanggan setia.
5. After-Sales Service - Follow up setelah pembelian.
6. Handle Complaints - Tanggapi keluhan dengan bijak dan cepat.', 'Service', '2026-04-25 09:23:53', '2026-04-25 09:23:53');
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(7, 'Inventory Management', 'Teknik manajemen inventori untuk mengoptimalkan stok dan mengurangi kerugian.', NULL, 'Manajemen inventori yang baik menghemat biaya dan mencegah kehilangan penjualan.

Metode manajemen stok:

1. FIFO (First In, First Out) - Produk yang masuk pertama, keluar pertama.
2. Minimum Stock Level - Tentukan batas minimum stok sebelum harus restock.
3. ABC Analysis - Kategorikan produk berdasarkan tingkat kepentingan.
4. Stock Opname Rutin - Hitung fisik stok secara berkala.

Tools manajemen inventori:
- Spreadsheet sederhana
- Aplikasi kasir dengan fitur inventori
- Barcode/QR code untuk tracking', 'Operations', '2026-04-25 09:23:53', '2026-04-25 09:23:53');
INSERT INTO `modules` (`id`, `title`, `description`, `thumbnail`, `content`, `category`, `created_at`, `updated_at`) VALUES(8, 'Digital Transformation for UMKM', 'Panduan langkah demi langkah untuk digitalisasi usaha UMKM.', NULL, 'Transformasi digital bukan pilihan, tapi keharusan untuk UMKM di era modern.

Langkah digitalisasi:

1. Kehadiran Online - Buat profil bisnis di Google, media sosial, dan marketplace.
2. Pembayaran Digital - Terima pembayaran via QRIS, e-wallet, transfer bank.
3. Pencatatan Digital - Ganti buku kas manual dengan aplikasi keuangan.
4. Pemasaran Digital - Manfaatkan media sosial dan iklan online.
5. E-Commerce - Jual produk di marketplace (Tokopedia, Shopee, dll).
6. Analisis Data - Gunakan data untuk membuat keputusan bisnis yang lebih baik.

Ingat: Mulai dari yang sederhana, lalu tingkatkan secara bertahap!', 'Technology', '2026-04-25 09:23:53', '2026-04-25 09:23:53');

